//! ✏️ Original command custody composes the actual source, authoring, native leaves and child publication.
use super::super::{FlowCommand,FlowSnapshot,FlowMutation};
use crate::editor::flow::host::{FlowComposedSourceWork,FlowComposedScene};
use super::super::child_publication::{FlowChildPublicationWork,FlowLeafWork,FlowLeafMode};
use flow::{FlowAuthoringWork,FlowAuthoringRequest,FlowAuthoringSerials,FlowCoreError};
use semio_plugin::{ChildContentView,AppOperationContext,ChildEmitPreparation,Emit,NoConfigMutation};
use semio_framework_job::{StepContext,OriginalTurnFailure,OriginalDomainReservation,OriginalSourceBinding,admit_original_domain_failure,close_original_retained_step};
use semio_framework_value::{RetireOwned,RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneRef,RetainedCloneClose,retained_clone_grant_admits}};
use std::mem::{ManuallyDrop,size_of};
type Infos=<flow::registry::catalogue_work::FlowOperatorInfoMap as std::ops::Deref>::Target;
type Output=Emit<FlowMutation,NoConfigMutation>;
type Reference=(u64,usize,usize,usize);
#[derive(Clone,Copy,PartialEq,Eq)]
struct Binding{source:OriginalSourceBinding,parent:Reference,command:Reference,infos:usize,operation:u64,generation:u64}
#[derive(RetireOwned)]
struct Outputs{core:Option<Vec<semio_framework_artifact_flow_flow::FlowMutation>>,native:Option<Vec<semio_s_artifact_stdio_semio_flow::schema::mutations::SemioFlowMutation>>,preparation:Option<ChildEmitPreparation>,emit:Option<Output>}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original Flow authoring command changed its retained authority")}
/// 🧵️ The surrounding job keeps the actual parent, command and preborn catalogue leases until terminal closure.
pub(crate) struct FlowAuthoringCommandWork{source:FlowComposedSourceWork,publication:FlowChildPublicationWork,authoring:Option<FlowAuthoringWork>,translation:Option<FlowLeafWork>,failure:OriginalDomainReservation<FlowCoreError>,outputs:ManuallyDrop<Option<Outputs>>,retirement:RetainedCloneClose,binding:Option<Binding>,serials:FlowAuthoringSerials,mode:FlowLeafMode,phase:u8,closing:bool}
impl FlowAuthoringCommandWork{
 pub(crate) fn new(serials:FlowAuthoringSerials,mode:FlowLeafMode)->Self{Self{source:FlowComposedSourceWork::new(),publication:FlowChildPublicationWork::new(),authoring:None,translation:None,failure:OriginalDomainReservation::new(),outputs:ManuallyDrop::new(Some(Outputs{core:None,native:None,preparation:None,emit:Some(Output::default())})),retirement:Default::default(),binding:None,serials,mode,phase:0,closing:false}}
 fn paid(cx:&mut StepContext<'_>,bytes:usize)->Result<bool,OriginalTurnFailure>{let d=RetirementDemand{copy_bytes:bytes,depth:1,..Default::default()};if cx.should_yield()||cx.is_cancelled()||!cx.retained_work_can_enter(d){return Ok(false)}cx.consume_fuel(1);cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()})?;Ok(true)}
 fn paid_close(cx:&mut StepContext<'_>,bytes:usize)->Result<bool,OriginalTurnFailure>{let d=RetirementDemand{copy_bytes:bytes,depth:1,..Default::default()};if cx.fuel_remaining()==0||cx.should_yield()||!cx.retained_work_can_enter(d){return Ok(false)}cx.consume_fuel(1);cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()})?;Ok(true)}
 pub(crate) fn step(&mut self,parent:RetainedCloneRef<'_,FlowSnapshot>,command:RetainedCloneRef<'_,FlowCommand>,children:&ChildContentView,operation:&AppOperationContext,infos:&Infos,request:FlowAuthoringRequest<'_>,cx:&mut StepContext<'_>)->Result<Option<Output>,OriginalTurnFailure>{for _ in 0..512{let before=(cx.fuel_remaining(),cx.retained_progress());if let Some(output)=self.once(parent,command,children,operation,infos,request,cx)?{return Ok(Some(output))}if cx.should_yield()||cx.is_cancelled()||before==(cx.fuel_remaining(),cx.retained_progress()){break}}Ok(None)}
 fn once(&mut self,parent:RetainedCloneRef<'_,FlowSnapshot>,command:RetainedCloneRef<'_,FlowCommand>,children:&ChildContentView,operation:&AppOperationContext,infos:&Infos,request:FlowAuthoringRequest<'_>,cx:&mut StepContext<'_>)->Result<Option<Output>,OriginalTurnFailure>{
  let binding=Binding{source:OriginalSourceBinding::borrow(cx),parent:parent.reference_identity(),command:command.reference_identity(),infos:infos as*const _ as usize,operation:cx.operation().0,generation:cx.generation().0};if self.closing||self.binding.is_some_and(|prior|prior!=binding)||operation.operation_id!=binding.operation||operation.generation!=binding.generation{return Err(invalid().into())}if cx.should_yield()||cx.is_cancelled(){return Ok(None)}if self.binding.is_none(){if Self::paid(cx,size_of::<Option<Binding>>())?{self.binding=Some(binding)}return Ok(None)}
  if self.failure.pending(){if let Some(failure)=admit_original_domain_failure(&mut self.failure,cx)?{return Err(failure)}return Ok(None)}
  match self.phase{
   0=>if self.publication.read_step(parent,command,children,operation,cx)?{let child=self.publication.child_source()?;if child.get().nodes.len()>super::super::FLOW_STORE_MAX_SCENE_ITEMS||child.get().edges.len()>super::super::FLOW_STORE_MAX_SCENE_ITEMS{return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"original qualified graph exceeds its declared scene extent").into())}self.phase=1},
   1=>if self.source.step(parent,Some(self.publication.child_source()?),cx)?{self.phase=2},
   2=>{if !self.failure.ready(){self.failure.prepare(cx)?;return Ok(None)}if Self::paid(cx,size_of::<FlowAuthoringWork>())?{self.authoring=Some(FlowAuthoringWork::new(self.serials));self.phase=3}},
   3=>{let source=self.source.read_source(parent.get())?;let authoring=self.authoring.as_mut().ok_or_else(invalid)?;let outputs=self.outputs.as_mut().ok_or_else(invalid)?;let mut serials=self.serials;let ready=self.failure.with_body(cx,|same,domain|{let Some(outcome)=authoring.step(&source,infos,request,same)?else{return Ok(false)};serials=outcome.serials;match outcome.result{Ok(leaves)=>outputs.core=Some(leaves),Err(error)=>*domain=Some(error)}Ok(true)})?;self.serials=serials;if ready==Some(true)&&!self.failure.pending(){authoring.begin_close();self.phase=4}},
   4=>{let authoring=self.authoring.as_mut().ok_or_else(invalid)?;if authoring.terminal_is_empty(){if Self::paid(cx,size_of::<FlowAuthoringWork>()+size_of::<FlowLeafWork>())?{self.authoring=None;self.translation=Some(FlowLeafWork::new(self.outputs.as_mut().ok_or_else(invalid)?.core.take().ok_or_else(invalid)?,self.mode));self.phase=5}}else{let d=authoring.next_close_demands(cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|g|authoring.close_step(g))?;}},
   5=>{let source=self.source.read_source(parent.get())?;let translation=self.translation.as_mut().ok_or_else(invalid)?;if let Some(output)=translation.step(&source,cx)?{self.outputs.as_mut().ok_or_else(invalid)?.native=Some(output);translation.begin_close();self.phase=6}},
   6=>{let translation=self.translation.as_mut().ok_or_else(invalid)?;if translation.terminal_is_empty(){if Self::paid(cx,size_of::<FlowLeafWork>())?{self.translation=None;self.phase=7}}else{let d=translation.close_demands(cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|g|translation.close_step(g))?;}},
   7=>{let outputs=self.outputs.as_mut().ok_or_else(invalid)?;if outputs.native.as_ref().is_some_and(Vec::is_empty){let d=self.retirement.next_owner_demands::<Vec<semio_s_artifact_stdio_semio_flow::schema::mutations::SemioFlowMutation>>(true,&None,cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|g|{let turn=self.retirement.begin_granted(&mut outputs.native,g);RetainedWorkOutcome{result:turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default()))),work:turn.work}})?;return Ok(None)}if !self.retirement.is_empty(){let d=self.retirement.demands(cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|g|self.retirement.step_granted(g))?;return Ok(None)}if outputs.native.is_none(){if Self::paid(cx,1)?{self.phase=9}return Ok(None)}if let Some(preparation)=self.publication.step(parent,command,children,operation,&mut outputs.native,cx)?{outputs.preparation=Some(preparation);self.phase=8}},
   8=>{let outputs=self.outputs.as_mut().ok_or_else(invalid)?;let emit=outputs.emit.as_mut().ok_or_else(invalid)?;let d=emit.child_preparation_admission_demands()?;if !cx.retained_work_can_enter(d){return Ok(None)}let turn=emit.admit_child_preparation_original(&mut outputs.preparation,cx.retained_grant());semio_framework_job::receive_original_retained_work(cx,turn)?;if outputs.preparation.is_none(){emit.ui_scope=semio_framework::kernel::UiDirtyScope::Full;self.phase=9}},
   9=>{if Self::paid(cx,2*size_of::<Output>())?{self.phase=10;return Ok(self.outputs.as_mut().ok_or_else(invalid)?.emit.take())}},
   _=>return Err(invalid().into())
  }Ok(None)
 }
 pub(crate) fn serials(&self)->FlowAuthoringSerials{self.serials}
 pub(crate) fn scene_alias_demand(&self)->Result<RetirementDemand,ValueError>{self.source.scene_alias_demand()}
 pub(crate) fn retain_scene(&self,g:RetainedCloneGrant)->RetainedWorkOutcome<Option<(FlowComposedScene,RetainedCloneProgress)>>{self.source.retain_scene(g)}
 pub(crate) fn restore_output(&mut self,output:Output){assert_eq!(self.phase,10);self.outputs.as_mut().expect("original authoring outputs").emit=Some(output);self.phase=9}
 pub(crate) fn begin_close(&mut self){self.closing=true;self.source.begin_close();self.publication.begin_close();if let Some(authoring)=self.authoring.as_mut(){authoring.begin_close()}if let Some(translation)=self.translation.as_mut(){translation.begin_close()}}
 pub(crate) fn close_demands(&self,copy:usize)->Result<RetirementDemand,ValueError>{if let Some(authoring)=self.authoring.as_ref(){return if authoring.terminal_is_empty(){Ok(RetirementDemand{copy_bytes:size_of::<usize>(),depth:1,..Default::default()})}else{authoring.next_close_demands(copy)}}if let Some(translation)=self.translation.as_ref(){return if translation.terminal_is_empty(){Ok(RetirementDemand{copy_bytes:size_of::<usize>(),depth:1,..Default::default()})}else{translation.close_demands(copy)}}if !self.source.terminal_is_empty(){return self.source.next_close_demands(copy)}if !self.publication.terminal_is_empty(){return self.publication.close_demands(copy)}if !self.failure.terminal_is_empty(){return self.failure.retirement_demands(copy)}if !self.retirement.is_empty(){return self.retirement.demands(copy)}if self.outputs.is_some(){return self.retirement.next_owner_demands::<Outputs>(true,&None,copy)}Ok(RetirementDemand{copy_bytes:size_of::<Option<Binding>>(),depth:1,..Default::default()})}
 pub(crate) fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<semio_framework_job::InteractiveJobCloseStep,OriginalTurnFailure>{
  use semio_framework_job::InteractiveJobCloseStep as Close;if !self.closing||self.binding.is_some_and(|binding|!binding.source.matches(cx)){return Err(invalid().into())}
  if let Some(authoring)=self.authoring.as_mut(){if !authoring.terminal_is_empty(){let d=authoring.next_close_demands(cx.retained_grant().maximum_copy_bytes)?;let step=close_original_retained_step(cx,d,|g|authoring.close_step(g))?;return Ok(Close::Pending{progress:step.progress()})}let paid=Self::paid_close(cx,size_of::<usize>())?;if paid{self.authoring=None}return Ok(Close::Pending{progress:RetainedCloneProgress{copied_items:usize::from(paid),copied_bytes:if paid{size_of::<usize>()}else{0},..Default::default()}})}
  if let Some(translation)=self.translation.as_mut(){if !translation.terminal_is_empty(){let d=translation.close_demands(cx.retained_grant().maximum_copy_bytes)?;let step=close_original_retained_step(cx,d,|g|translation.close_step(g))?;return Ok(Close::Pending{progress:step.progress()})}let paid=Self::paid_close(cx,size_of::<usize>())?;if paid{self.translation=None}return Ok(Close::Pending{progress:RetainedCloneProgress{copied_items:usize::from(paid),copied_bytes:if paid{size_of::<usize>()}else{0},..Default::default()}})}
  if !self.source.terminal_is_empty(){return self.source.close_step(cx).map(|step|match step{Close::Complete{progress}=>Close::Pending{progress},step=>step})}
  let d=self.close_demands(cx.retained_grant().maximum_copy_bytes)?;let step=close_original_retained_step(cx,d,|g|{
   if !self.publication.terminal_is_empty(){return self.publication.close_step(g)}if !self.failure.terminal_is_empty(){return self.failure.close_step(g)}if !self.retirement.is_empty(){return self.retirement.step_granted(g)}if self.outputs.is_some(){let turn=self.retirement.begin_granted(&mut self.outputs,g);return RetainedWorkOutcome{result:turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default()))),work:turn.work}}
   if self.binding.is_none(){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}if !retained_clone_grant_admits(g,d){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}self.binding=None;RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})),work:1}
  })?;Ok(if self.terminal_is_empty(){Close::Complete{progress:step.progress()}}else{Close::Pending{progress:step.progress()}})
 }
 pub(crate) fn terminal_is_empty(&self)->bool{self.closing&&self.authoring.is_none()&&self.translation.is_none()&&self.source.terminal_is_empty()&&self.publication.terminal_is_empty()&&self.failure.terminal_is_empty()&&self.outputs.is_none()&&self.retirement.is_empty()&&self.binding.is_none()}
}
impl Drop for FlowAuthoringCommandWork{fn drop(&mut self){assert!(self.terminal_is_empty(),"original Flow authoring command must close source, domain and native output custody");unsafe{ManuallyDrop::drop(&mut self.outputs)}}}
